SET FOREIGN_KEY_CHECKS=0;
DROP TABLE IF EXISTS `investment_requests_respaldo`;
CREATE TABLE `investment_requests_respaldo` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `user_id` bigint unsigned NOT NULL,
  `investor_id` bigint unsigned DEFAULT NULL,
  `paquete_inversion_id` bigint unsigned NOT NULL,
  `prospecto_id` bigint unsigned DEFAULT NULL,
  `monto` decimal(15,2) NOT NULL,
  `comprobante_path` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `status` enum('pending','approved','rejected') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pending',
  `rejection_reason` text COLLATE utf8mb4_unicode_ci,
  `reviewed_at` timestamp NULL DEFAULT NULL,
  `reviewed_by` bigint unsigned DEFAULT NULL,
  `extra_data` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `investment_requests_user_id_foreign` (`user_id`),
  KEY `investment_requests_paquete_inversion_id_foreign` (`paquete_inversion_id`),
  KEY `investment_requests_prospecto_id_foreign` (`prospecto_id`),
  KEY `investment_requests_reviewed_by_foreign` (`reviewed_by`),
  KEY `investment_requests_investor_id_foreign` (`investor_id`),
  CONSTRAINT `investment_requests_chk_1` CHECK (json_valid(`extra_data`))
) ENGINE=InnoDB AUTO_INCREMENT=1105 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
